import torch
import torch.nn as nn

# PTX source for GELU (exact formulation using erf.approx)
PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry gelu_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 N
)
{
    .reg .pred   %p;
    .reg .u32    %r<7>;
    .reg .u64    %rd<7>;
    .reg .f32    %f<8>;
    .reg .f16    %h<3>;

    // Load kernel parameters
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [output_ptr];
    ld.param.u64 %rd3, [N];

    // Thread identifiers
    mov.u32 %r1, %tid.x;          // threadIdx.x
    mov.u32 %r2, %ctaid.x;        // blockIdx.x
    mov.u32 %r3, %ntid.x;         // blockDim.x
    mad.lo.s32 %r4, %r2, %r3, %r1; // global linear thread id

    // Total number of threads in the grid
    mov.u32 %r5, %nctaid.x;        // gridDim.x
    mad.lo.s32 %r6, %r5, %r3, 0;   // gridDim.x * blockDim.x

    // Convert to 64‑bit for address arithmetic
    cvt.u64.u32 %rd4, %r4;          // idx
    cvt.u64.u32 %rd5, %r6;          // stride

    // Constants (half, one, 1/sqrt(2))
    mov.f32 %f1, 0.5;               // 0.5
    mov.f32 %f2, 1.0;               // 1.0
    mov.f32 %f3, 0.7071067811865475; // 1/√2

LOOP:
    // if (idx >= N) break;
    setp.ge.u64 %p, %rd4, %rd3;
    @%p bra DONE;

    // Load fp16 element
    ld.global.b16 %h1, [%rd1 + %rd4*2];
    // Convert to fp32
    cvt.f32.f16 %f4, %h1;

    // x / √2
    mul.f32 %f5, %f4, %f3;

    // erf approximation (built‑in PTX intrinsic)
    erf.approx.f32 %f6, %f5;

    // 0.5 * x * (1 + erf)
    add.f32 %f7, %f2, %f6;   // 1 + erf
    mul.f32 %f7, %f7, %f4;   // x * (1 + erf)
    mul.f32 %f7, %f7, %f1;   // 0.5 * ...

    // Convert back to fp16 (round‑to‑nearest)
    cvt.rn.f16.f32 %h2, %f7;

    // Store result
    st.global.b16 [%rd2 + %rd4*2], %h2;

    // idx += stride
    add.u64 %rd4, %rd4, %rd5;
    bra LOOP;

DONE:
    ret;
}
"""

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference GELU model using a custom PTX kernel.
    """
    def __init__(self):
        super().__init__()
        # Load PTX module via the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is fp16
        assert x.dtype == torch.float16, "Model expects fp16 input"
        out = torch.empty_like(x, dtype=torch.float16)

        # Total element count
        N = x.numel()

        # Launch configuration (256 threads per block)
        block = (256, 1, 1)
        grid_x = (N + block[0] - 1) // block[0]
        grid = (grid_x, 1, 1)

        # Arguments: input ptr, output ptr, element count
        args = [x.data_ptr(), out.data_ptr(), N]

        # Launch the PTX kernel
        ptx_launch(self.module, "gelu_kernel", grid, block, args)

